script:
def walk(path):
    out = []
    for name in repo.list(path):
        full = path + "/" + name if path != "." else name
        if name.endswith("/"):
            out.extend(walk(full.rstrip("/")))
        else:
            out.append(full)
    return out

files = walk("src")
info = {}
for f in files:
    c = repo.read(f)
    info[f] = {"len": len(c), "content": c}
result(info)

